1	package release
2	
3	import (
4		"encoding/json"
5		"errors"
6		"fmt"
7		"os"
8		"path/filepath"
9		"sync"
10		"syscall"
11	)
12	
13	const (
14		stateFileName = "ledger.json"
15		lockFileName  = "ledger.lock"
16		stateVersion  = 1
17	)
18	
19	// Store 是一个本地配方批次台账，数据保存在调用方指定的目录中。
20	// 不同目录互相独立；多个 Store 可以安全并发提交（进程内互斥、进程间文件锁）。
21	type Store struct {
22		dir      string
23		lockFile *os.File
24		mu       sync.Mutex
25		state    *persistedState
26	}
27	
28	// Open 打开（或首次使用）位于 dir 的台账。
29	// 目录不存在时会创建；目录中没有台账文件时得到空台账；
30	// 台账文件已存在但没有任何内容（零字节，无论原本就是空文件还是使用中被截断）
31	// 时按损坏处理；已有台账文件无法读取、解析，任一配方版本的任一物料每份克数不是正数，
32	// 任一配方版本内同一物料编号出现多次，
33	// 任一批次绑定的配方版本未登记，
34	// 已保存投料的物料编号不属于该批次绑定的配方版本，
35	// 或已保存的投料数量非法（单条不是正数，或同一批次同一物料累计实投
36	// 超过 9223372036854775.807 克）时，返回 ErrCorruptData（可用 errors.Is
37	// 判断），不会当成空台账继续保存，也不会返回可继续使用的台账对象。
38	func Open(dir string) (*Store, error) {
39		if dir == "" {
40			return nil, errors.New("数据位置不能为空")
41		}
42		if err := os.MkdirAll(dir, 0o755); err != nil {
43			return nil, fmt.Errorf("创建数据位置 %q 失败: %w", dir, err)
44		}
45		info, err := os.Stat(dir)
46		if err != nil {
47			return nil, fmt.Errorf("读取数据位置 %q 失败: %w", dir, err)
48		}
49		if !info.IsDir() {
50			return nil, fmt.Errorf("数据位置 %q 不是目录", dir)
51		}
52	
53		lockPath := filepath.Join(dir, lockFileName)
54		lf, err := os.OpenFile(lockPath, os.O_CREATE|os.O_RDWR, 0o644)
55		if err != nil {
56			return nil, fmt.Errorf("打开锁文件失败: %w", err)
57		}
58	
59		s := &Store{dir: dir, lockFile: lf}
60		if err := s.load(); err != nil {
61			lf.Close()
62			return nil, err
63		}
64		return s, nil
65	}
66	
67	// Close 释放台账占用的文件锁。
68	func (s *Store) Close() error {
69		s.mu.Lock()
70		defer s.mu.Unlock()
71		if s.lockFile == nil {
72			return nil
73		}
74		err := s.lockFile.Close()
75		s.lockFile = nil
76		return err
77	}
78	
79	func (s *Store) lockExclusive() error {
80		if s.lockFile == nil {
81			return errors.New("台账已关闭")
82		}
83		if err := syscall.Flock(int(s.lockFile.Fd()), syscall.LOCK_EX); err != nil {
84			return fmt.Errorf("锁定台账失败: %w", err)
85		}
86		return nil
87	}
88	
89	func (s *Store) lockShared() error {
90		if s.lockFile == nil {
91			return errors.New("台账已关闭")
92		}
93		if err := syscall.Flock(int(s.lockFile.Fd()), syscall.LOCK_SH); err != nil {
94			return fmt.Errorf("锁定台账失败: %w", err)
95		}
96		return nil
97	}
98	
99	func (s *Store) unlock() {
100		_ = syscall.Flock(int(s.lockFile.Fd()), syscall.LOCK_UN)
101	}
102	
103	func (s *Store) load() error {
104		data, err := os.ReadFile(filepath.Join(s.dir, stateFileName))
105		if err != nil {
106			if os.IsNotExist(err) {
107				s.state = &persistedState{Version: stateVersion, Requests: map[string]*requestRecord{}}
108				return nil
109			}
110			return fmt.Errorf("%w: 读取台账文件失败: %v", ErrCorruptData, err)
111		}
112		if len(data) == 0 {
113			// 区分“没有台账文件”与“已有文件但内容为空”：文件不存在才算首次使用，
114			// 零字节文件（原本就为空或使用中被截断）一律按损坏处理——既不能当成
115			// 空台账补写，也不能凭内存中的旧记录还原，调用方必须明确知道无法读取。
116			return fmt.Errorf("%w: 台账文件 %q 没有内容", ErrCorruptData, filepath.Join(s.dir, stateFileName))
117		}
118		var st persistedState
119		if err := json.Unmarshal(data, &st); err != nil {
120			return fmt.Errorf("%w: 台账文件解析失败: %v", ErrCorruptData, err)
121		}
122		if st.Version != stateVersion {
123			return fmt.Errorf("%w: 台账版本 %d 不受支持", ErrCorruptData, st.Version)
124		}
125		if err := validateState(&st); err != nil {
126			return err
127		}
128		if st.Requests == nil {
129			st.Requests = map[string]*requestRecord{}
130		}
131		s.state = &st
132		return nil
133	}
134	
135	// validateState 检查台账的引用完整性与数量合法性：
136	//   - 每个配方版本的每种物料，每份克数必须是正数——与登记时的规则一致。
137	//     任一版本（包括尚未被任何批次使用的版本）的任一物料为零或负数，
138	//     整份台账即视为损坏：不能改成最小用量、取绝对值、删除问题物料
139	//     或改用其他版本后继续，其他配方完整或批次数量恰好吻合也不能放行。
140	//   - 同一配方版本的物料列表内，每个物料编号只能出现一次——与登记时的
141	//     规则一致。任一版本（包括尚未被任何批次使用的版本）内同一物料编号
142	//     出现多次，整份台账即视为损坏：不能合并重复项、相加克数、丢弃其中
143	//     一条或由查询者挑一项作为依据，即使两条克数完全相同也不能放行；
144	//     不同版本、不同配方各自使用同一物料编号不受影响。
145	//   - 每个批次记录的配方编号与版本号必须共同指向一个已登记的配方版本。
146	//     任一批次找不到对应版本，整份台账即视为损坏——不能改用同编号的其他版本，
147	//     也不能按名称或物料内容替换，即使其他批次仍然完整也不能放行本次读取。
148	//   - 每条已保存的投料数量必须是正数；同一批次内同一物料的累计实投
149	//     不得超过 maxGramsMilli（9223372036854775.807 克）。任一记录为零或
150	//     负数，或任一物料累计超限，整份台账即视为损坏——负数记录即使能被
151	//     正数抵消回范围内也不接受，超限也不能截断或忽略后继续。
152	//   - 每条已保存投料的物料编号必须属于该批次绑定的配方版本。归属以批次
153	//     实际绑定的版本为准：物料只出现在同编号的其他版本或其他配方中，
154	//     不能作为接受依据；也不能改选版本、补入物料或丢弃问题投料后继续。
155	func validateState(st *persistedState) error {
156		for _, r := range st.Recipes {
157			if r == nil {
158				return fmt.Errorf("%w: 台账中存在空的配方记录", ErrCorruptData)
159			}
160			seen := make(map[string]bool, len(r.Materials))
161			for _, m := range r.Materials {
162				if seen[m.MaterialNo] {
163					return fmt.Errorf("%w: 配方 %q 版本 %q 的物料编号 %q 重复",
164						ErrCorruptData, r.RecipeNo, r.Version, m.MaterialNo)
165				}
166				seen[m.MaterialNo] = true
167				if m.GramsMilli <= 0 {
168					return fmt.Errorf("%w: 配方 %q 版本 %q 物料 %q 的每份克数不是正数",
169						ErrCorruptData, r.RecipeNo, r.Version, m.MaterialNo)
170				}
171			}
172		}
173		for _, b := range st.Batches {
174			if b == nil {
175				return fmt.Errorf("%w: 台账中存在空的批次记录", ErrCorruptData)
176			}
177			r := findRecipe(st, b.RecipeNo, b.RecipeVersion)
178			if r == nil {
179				return fmt.Errorf("%w: 批次 %q 绑定的配方 %q 版本 %q 未登记",
180					ErrCorruptData, b.BatchNo, b.RecipeNo, b.RecipeVersion)
181			}
182			if err := validateFeedings(b, r); err != nil {
183				return err
184			}
185		}
186		return nil
187	}
188	
189	// validateFeedings 检查一个批次内已保存投料的合法性与配方归属。
190	// 归属以批次绑定的配方版本 r 为准：每条投料的物料编号必须在 r 的物料
191	// 列表中，否则整份台账视为损坏。数量方面只判断数量本身是否合法，不判断
192	// 实投是否符合配方：无投料的物料累计为零属正常，不足或超过应投量也不
193	// 在此拒绝。
194	func validateFeedings(b *batchRecord, r *recipeRecord) error {
195		acc := newFeedingAccumulator()
196		for _, f := range b.Feedings {
197			belongs := false
198			for _, m := range r.Materials {
199				if m.MaterialNo == f.MaterialNo {
200					belongs = true
201					break
202				}
203			}
204			if !belongs {
205				return fmt.Errorf("%w: 批次 %q 的第 %d 条投料物料 %q 不属于其绑定的配方 %q 版本 %q",
206					ErrCorruptData, b.BatchNo, f.Seq, f.MaterialNo, b.RecipeNo, b.RecipeVersion)
207			}
208			if f.GramsMilli <= 0 {
209				return fmt.Errorf("%w: 批次 %q 物料 %q 的第 %d 条投料数量不是正数",
210					ErrCorruptData, b.BatchNo, f.MaterialNo, f.Seq)
211			}
212			if !acc.add(f.MaterialNo, f.GramsMilli) {
213				return fmt.Errorf("%w: 批次 %q 物料 %q 的累计实投超出上限 %s 克",
214					ErrCorruptData, b.BatchNo, f.MaterialNo, maxGramsMilli)
215			}
216		}
217		return nil
218	}
219	
220	// persist 先写临时文件再原子改名，并 fsync 目录，保证已提交数据可恢复。
221	func (s *Store) persist(st *persistedState) error {
222		data, err := json.MarshalIndent(st, "", "  ")
223		if err != nil {
224			return err
225		}
226		tmpPath := filepath.Join(s.dir, stateFileName+".tmp")
227		f, err := os.OpenFile(tmpPath, os.O_CREATE|os.O_WRONLY|os.O_TRUNC, 0o644)
228		if err != nil {
229			return err
230		}
231		if _, err := f.Write(data); err != nil {
232			f.Close()
233			return err
234		}
235		if err := f.Sync(); err != nil {
236			f.Close()
237			return err
238		}
239		if err := f.Close(); err != nil {
240			return err
241		}
242		if err := os.Rename(tmpPath, filepath.Join(s.dir, stateFileName)); err != nil {
243			return err
244		}
245		if d, err := os.Open(s.dir); err == nil {
246			_ = d.Sync()
247			_ = d.Close()
248		}
249		return nil
250	}
251	
252	func cloneState(st *persistedState) (*persistedState, error) {
253		data, err := json.Marshal(st)
254		if err != nil {
255			return nil, err
256		}
257		var out persistedState
258		if err := json.Unmarshal(data, &out); err != nil {
259			return nil, err
260		}
261		if out.Requests == nil {
262			out.Requests = map[string]*requestRecord{}
263		}
264		return &out, nil
265	}
266	
267	// write 是所有写入操作的统一入口：
268	//   - reqNo 为空直接报错；
269	//   - 同一 reqNo 且操作与内容完全相同，返回第一次成功的结果（幂等重放）；
270	//   - 同一 reqNo 用于其他操作或不同内容，返回 ErrRequestConflict；
271	//   - apply 在状态副本上执行，返回校验错误时不落盘、不占用请求编号；
272	//   - apply 成功后，状态与请求记录一起原子落盘，再切换到内存状态。
273	func (s *Store) write(reqNo, op string, payload any, apply func(*persistedState) (json.RawMessage, error), out any) error {
274		if reqNo == "" {
275			return errors.New("请求编号不能为空")
276		}
277		s.mu.Lock()
278		defer s.mu.Unlock()
279		if err := s.lockExclusive(); err != nil {
280			return err
281		}
282		defer s.unlock()
283	
284		// 跨进程场景下，其他进程可能已提交新数据；加锁后重新加载，
285		// 确保在最新状态上应用变更，避免用旧快照覆盖其他进程的写入。
286		if err := s.load(); err != nil {
287			return err
288		}
289	
290		payloadRaw, err := json.Marshal(payload)
291		if err != nil {
292			return err
293		}
294		payloadStr := string(payloadRaw)
295	
296		if req, ok := s.state.Requests[reqNo]; ok {
297			if req.Op != op || req.Payload != payloadStr {
298				return fmt.Errorf("%w: 请求编号 %q 已用于操作 %q，不能再用于操作 %q 或不同内容",
299					ErrRequestConflict, reqNo, req.Op, op)
300			}
301			if err := json.Unmarshal(req.Result, out); err != nil {
302				return fmt.Errorf("重放请求 %q 的结果失败: %w", reqNo, err)
303			}
304			return nil
305		}
306	
307		clone, err := cloneState(s.state)
308		if err != nil {
309			return err
310		}
311		result, err := apply(clone)
312		if err != nil {
313			return err
314		}
315		clone.Requests[reqNo] = &requestRecord{Op: op, Payload: payloadStr, Result: result}
316		if err := s.persist(clone); err != nil {
317			return fmt.Errorf("保存台账失败: %w", err)
318		}
319		s.state = clone
320		if err := json.Unmarshal(result, out); err != nil {
321			return fmt.Errorf("解析请求结果失败: %w", err)
322		}
323		return nil
324	}
325	
326	// read 在共享锁下读取当前状态。
327	func (s *Store) read(fn func(*persistedState) error) error {
328		s.mu.Lock()
329		defer s.mu.Unlock()
330		if err := s.lockShared(); err != nil {
331			return err
332		}
333		defer s.unlock()
334		if err := s.load(); err != nil {
335			return err
336		}
337		return fn(s.state)
338	}
339	
340	// 视图构造：每次都从记录全新构造，返回的切片与内部状态完全隔离。
341	
342	func buildRecipeView(r *recipeRecord) *RecipeView {
343		mats := make([]MaterialView, 0, len(r.Materials))
344		for _, m := range r.Materials {
345			mats = append(mats, MaterialView{MaterialNo: m.MaterialNo, Grams: m.GramsMilli.String()})
346		}
347		return &RecipeView{RecipeNo: r.RecipeNo, Version: r.Version, Name: r.Name, Materials: mats}
348	}
349	
350	func buildBatchView(b *batchRecord, r *recipeRecord) (*BatchView, error) {
351		v := &BatchView{
352			BatchNo:         b.BatchNo,
353			RecipeNo:        r.RecipeNo,
354			RecipeVersion:   r.Version,
355			RecipeName:      r.Name,
356			PlannedPortions: b.PlannedPortions,
357			Status:          b.Status,
358			Feedings:        make([]FeedingView, 0, len(b.Feedings)),
359			Materials:       make([]MaterialRequirement, 0, len(r.Materials)),
360		}
361	
362		for _, f := range b.Feedings {
363			v.Feedings = append(v.Feedings, FeedingView{
364				Seq:        f.Seq,
