14	// 构造一个物料编号重复的配方版本记录。
15	func recipeDup(recipeNo, version string, grams1, grams2 gramsMilli) *recipeRecord {
16		return &recipeRecord{RecipeNo: recipeNo, Version: version, Name: "配方",
17			Materials: []materialRecord{
18				{MaterialNo: "M1", GramsMilli: grams1},
19				{MaterialNo: "M1", GramsMilli: grams2},
20			}}
21	}
22	
23	// Open 时只要任一配方版本内同一物料编号出现多次就必须返回 ErrCorruptData：
24	// 两条克数不同、完全相同、该版本未被任何批次选用，三种情形都拒绝；
25	// 错误信息需包含配方编号、版本号与重复的物料编号；
26	// 不返回可用的台账对象，也不改写原文件。
27	func TestOpenRejectsDuplicateMaterialInRecipeVersion(t *testing.T) {
28		cases := []struct {
29			name    string
30			grams1  gramsMilli
31			grams2  gramsMilli
32			withUse bool // 是否有批次绑定该版本
33		}{
34			{"克数不同且有批次绑定", 100000, 200000, true},
35			{"克数完全相同", 100000, 100000, true},
36			{"版本未被任何批次选用", 100000, 200000, false},
37		}
38		for _, tc := range cases {
39			t.Run(tc.name, func(t *testing.T) {
40				dir := t.TempDir()
41				st := &persistedState{
42					Version: stateVersion,
43					Recipes: []*recipeRecord{
44						recipeR1v1(),
45						recipeDup("R2", "v1", tc.grams1, tc.grams2),
46					},
47				}
48				if tc.withUse {
49					st.Batches = []*batchRecord{{
50						BatchNo: "B1", RecipeNo: "R2", RecipeVersion: "v1",
51						PlannedPortions: 2, Status: StatusExecuting,
52					}}
53				}
54				original := writeStateFile(t, dir, st)
55	
56				s, err := Open(dir)
57				if !errors.Is(err, ErrCorruptData) {
58					t.Fatalf("配方版本内物料重复应返回 ErrCorruptData，得到 %v", err)
59				}
60				if s != nil {
61					s.Close()
62					t.Fatalf("损坏台账不应返回可用的 Store 对象")
63				}
64				msg := err.Error()
65				for _, want := range []string{"R2", "v1", "M1"} {
66					if !strings.Contains(msg, want) {
67						t.Fatalf("错误信息应包含 %q，得到 %v", want, err)
68					}
69				}
70				// 原台账内容保留：不得合并重复项、相加克数或丢弃其中一条。
71				got, err := os.ReadFile(filepath.Join(dir, stateFileName))
72				if err != nil {
73					t.Fatal(err)
74				}
75				if !bytes.Equal(got, original) {
76					t.Fatalf("拒绝打开不应改动台账文件")
77				}
78			})
79		}
80	}
81	
82	// 台账里其他配方与批次都完整也不能绕过：只要一个版本物料重复，Open 整体失败。
83	func TestOpenDuplicateMaterialAmongCompleteRecords(t *testing.T) {
84		dir := t.TempDir()
85		writeStateFile(t, dir, &persistedState{
86			Version: stateVersion,
87			Recipes: []*recipeRecord{
88				recipeR1v1(),
89				recipeDup("R2", "v1", 100000, 200000),
90			},
91			Batches: []*batchRecord{
92				{BatchNo: "B-ok", RecipeNo: "R1", RecipeVersion: "v1", PlannedPortions: 1, Status: StatusClosed},
93			},
94		})
95		if _, err := Open(dir); !errors.Is(err, ErrCorruptData) {
96			t.Fatalf("存在完整配方与批次也应整体拒绝，得到 %v", err)
97		}
98	}
99	
100	// 台账打开后本地文件被改坏（配方版本内物料编号重复）：
101	// 下一次查询或写入都必须返回 ErrCorruptData，不得返回部分结果、
102	// 不得返回重复的数量核对项、不得保存新记录或改变已有批次；
103	// 被拒绝的写入不留业务记录、不占用请求编号；恢复后原记录继续可用。
104	func TestDuplicateMaterialAfterOpenDetectedOnNextAccess(t *testing.T) {
105		dir := t.TempDir()
106		s, err := Open(dir)
107		if err != nil {
108			t.Fatal(err)
109		}
110		defer s.Close()
111	
112		if _, err := s.RegisterRecipe("r1", "R1", "v1", "配方一", []MaterialInput{
113			{MaterialNo: "M1", Grams: "100"},
114		}); err != nil {
115			t.Fatal(err)
116		}
117		if _, err := s.RegisterRecipe("r2", "R2", "v1", "配方二", []MaterialInput{
118			{MaterialNo: "M2", Grams: "5"},
119		}); err != nil {
120			t.Fatal(err)
121		}
122		if _, err := s.CreateBatch("b1", "B1", "R1", "v1", 2); err != nil {
123			t.Fatal(err)
124		}
125		if _, err := s.StartBatch("s1", "B1"); err != nil {
126			t.Fatal(err)
127		}
128		fixedTime := time.Date(2026, 8, 1, 9, 0, 0, 0, time.UTC)
129		if _, err := s.AddFeeding("feed-1", "B1", "M1", "50", fixedTime, "张三"); err != nil {
130			t.Fatal(err)
131		}
132	
133		// 保存完好时的文件内容，随后把 R2/v1 改成 M2 重复两次（B1 绑定的 R1/v1 仍完整）。
134		good, err := os.ReadFile(filepath.Join(dir, stateFileName))
135		if err != nil {
136			t.Fatal(err)
137		}
138		var broken persistedState
139		if err := json.Unmarshal(good, &broken); err != nil {
140			t.Fatal(err)
141		}
142		for _, r := range broken.Recipes {
143			if r.RecipeNo == "R2" && r.Version == "v1" {
144				r.Materials = append(r.Materials, materialRecord{MaterialNo: "M2", GramsMilli: 9000})
145			}
146		}
147		badBytes := writeStateFile(t, dir, &broken)
148	
